"""The target repo's working copy: clone, venv, dependency pins, tests, git checkpoints."""

import os
import re
import shutil
import subprocess
import tomllib
from dataclasses import dataclass
from pathlib import Path

import neatlogs
from packaging.requirements import InvalidRequirement, Requirement
from packaging.utils import canonicalize_name

SKIP_DIRS = {".git", ".venv", "venv", "node_modules", "__pycache__", ".tox", ".mypy_cache", ".pytest_cache"}
OUTPUT_CAP = 12000


def sh(cmd: list[str], cwd: str | Path | None = None, timeout: int = 900, env: dict | None = None) -> subprocess.CompletedProcess:
    return subprocess.run(cmd, cwd=cwd, capture_output=True, text=True, timeout=timeout,
                          env={**os.environ, **(env or {})})


def tail(text: str, limit: int = OUTPUT_CAP) -> str:
    return text if len(text) <= limit else "...[truncated]...\n" + text[-limit:]


@dataclass
class TestRun:
    exit_code: int
    failing: set[str]
    output: str
    collection_error: bool

    @property
    def summary(self) -> str:
        last = [l for l in self.output.strip().splitlines() if l.strip()][-1:] or ["(no output)"]
        return last[0]


FAILING_LINE = re.compile(r"^(FAILED|ERROR) (\S+)")


def parse_pytest(exit_code: int, output: str) -> TestRun:
    failing = set()
    for line in output.splitlines():
        m = FAILING_LINE.match(line)
        if m:
            failing.add(m.group(2))
    collection_error = "error" in output.lower() and ("during collection" in output or "ImportError" in output)
    return TestRun(exit_code, failing, output, collection_error)


class Workspace:
    def __init__(self, root: Path, python: str = "3.12"):
        self.root = Path(root)             # the run directory
        self.repo = self.root / "repo"     # working copy of the target repo
        self.venv = self.root / "venv"
        self.python = python

    @property
    def py(self) -> str:
        return str(self.venv / "bin" / "python")

    @property
    def test_cmd(self) -> str:
        return f"{self.py} -m pytest -q -rfE -p no:cacheprovider"

    # --- setup -------------------------------------------------------------

    def clone(self, source: str, branch: str) -> None:
        src = Path(source).expanduser()
        if src.exists() and not (src / ".git").exists():
            shutil.copytree(src, self.repo, ignore=shutil.ignore_patterns(*SKIP_DIRS))
            self.git("init", "-q")
            self.git("add", "-A")
            self.git("commit", "-q", "-m", "upshift: baseline snapshot")
        else:
            out = sh(["git", "clone", "-q", str(src) if src.exists() else source, str(self.repo)])
            if out.returncode != 0:
                raise RuntimeError(f"git clone failed: {out.stderr.strip()}")
        self.git("checkout", "-q", "-b", branch)

    def git(self, *args: str) -> str:
        out = sh(["git", "-c", "user.name=upshift", "-c", "user.email=upshift@localhost", *args], cwd=self.repo)
        if out.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)} failed: {out.stderr.strip()}")
        return out.stdout

    @neatlogs.span(kind="TOOL", tool_name="install")
    def install(self) -> str:
        """Create the venv and install the project plus pytest. Returns a log of what ran."""
        log = []
        if not self.venv.exists():
            out = sh(["uv", "venv", "-q", "--python", self.python, str(self.venv)])
            if out.returncode != 0:
                raise RuntimeError(f"uv venv failed: {out.stderr.strip()}")
        pip = ["uv", "pip", "install", "-q", "--python", self.py]
        for req in self.requirement_files():
            out = sh([*pip, "-r", str(req)], cwd=self.repo)
            log.append(f"{req.name}: exit {out.returncode} {out.stderr.strip()[-500:]}")
            if out.returncode != 0:
                raise RuntimeError(f"installing {req.name} failed:\n{tail(out.stderr, 3000)}")
        if (self.repo / "pyproject.toml").exists() or (self.repo / "setup.py").exists():
            for target in (".[test,dev]", ".[test]", ".[dev]", "."):
                out = sh([*pip, "-e", target], cwd=self.repo)
                if out.returncode == 0:
                    log.append(f"installed -e {target}")
                    break
            else:
                raise RuntimeError(f"installing the project failed:\n{tail(out.stderr, 3000)}")
        sh([*pip, "pytest"])
        return "\n".join(log)

    # --- dependency pins ---------------------------------------------------

    def requirement_files(self) -> list[Path]:
        return sorted(p for p in self.repo.glob("requirements*.txt") if p.is_file())

    def installed_version(self, package: str) -> str | None:
        out = sh([self.py, "-c", "import importlib.metadata as m, sys; print(m.version(sys.argv[1]))", package])
        return out.stdout.strip() if out.returncode == 0 else None

    def pin_files(self, package: str) -> list[Path]:
        """Files in the repo that declare `package`."""
        found = []
        for path in [*self.requirement_files(), self.repo / "pyproject.toml"]:
            if path.exists() and _find_requirement(path.read_text(), package):
                found.append(path)
        return found

    @neatlogs.span(kind="TOOL", tool_name="set_version")
    def set_version(self, package: str, version: str) -> str:
        """Rewrite the package's pins to the target version and install it."""
        changed = []
        for path in self.pin_files(package):
            text = path.read_text()
            new = _rewrite_requirement(text, package, version)
            if new != text:
                path.write_text(new)
                changed.append(path.name)
        out = sh(["uv", "pip", "install", "-q", "--python", self.py, f"{package}=={version}"], cwd=self.repo)
        if out.returncode != 0:
            raise RuntimeError(f"installing {package}=={version} failed:\n{tail(out.stderr, 4000)}")
        return f"pins updated in {changed or 'no files'}; installed {package}=={version}"

    # --- tests ---------------------------------------------------------------

    @neatlogs.span(kind="TOOL", tool_name="run_tests")
    def run_tests(self, selector: str = "") -> TestRun:
        cmd = [self.py, "-m", "pytest", "-q", "-rfE", "-p", "no:cacheprovider", "--no-header"]
        if selector:
            cmd += selector.split()
        try:
            out = sh(cmd, cwd=self.repo, timeout=1200)
        except subprocess.TimeoutExpired:
            return TestRun(-1, {"<timeout>"}, "pytest timed out after 1200s", False)
        return parse_pytest(out.returncode, out.stdout + out.stderr)

    # --- files ---------------------------------------------------------------

    def resolve(self, rel: str) -> Path:
        path = (self.repo / rel).resolve()
        if self.repo.resolve() not in path.parents and path != self.repo.resolve():
            raise ValueError(f"{rel} is outside the repo")
        return path

    def source_files(self):
        for path in self.repo.rglob("*"):
            if path.is_file() and not any(part in SKIP_DIRS for part in path.relative_to(self.repo).parts):
                yield path


# --- requirement parsing helpers ---------------------------------------------

def _req_name(spec: str) -> str | None:
    try:
        return canonicalize_name(Requirement(spec).name)
    except InvalidRequirement:
        return None


def _find_requirement(text: str, package: str) -> bool:
    target = canonicalize_name(package)
    return any(_req_name(m.group(2)) == target for m in _REQ_STRING.finditer(text)) or any(
        _req_name(line.split("#")[0].strip()) == target for line in text.splitlines()
        if line.strip() and not line.strip().startswith(("#", "-"))
    )


# a quoted requirement string inside pyproject.toml
_REQ_STRING = re.compile(r"""(["'])([A-Za-z0-9][A-Za-z0-9._\-\[\], ]*\s*(?:[<>=!~;].*?)?)\1""")


def _new_spec(old: str, package: str, version: str) -> str:
    req = Requirement(old)
    extras = f"[{','.join(sorted(req.extras))}]" if req.extras else ""
    pinned = any(s.operator == "==" for s in req.specifier)
    marker = f"; {req.marker}" if req.marker else ""
    return f"{req.name}{extras}{'==' if pinned else '>='}{version}{marker}"


def _rewrite_requirement(text: str, package: str, version: str) -> str:
    target = canonicalize_name(package)
    lines = []
    for line in text.splitlines(keepends=True):
        body, sep, comment = line.partition("#")
        stripped = body.strip()
        if stripped and not stripped.startswith("-") and "=" not in stripped.split("[")[0].split(" ")[0][:0] \
                and _req_name(stripped) == target and not stripped.startswith(("[", '"', "'")):
            newline = "\n" if line.endswith("\n") else ""
            lines.append(_new_spec(stripped, package, version) + (f"  #{comment.rstrip()}" if sep else "") + newline)
            continue
        lines.append(line)
    text = "".join(lines)

    def swap(m: re.Match) -> str:
        spec = m.group(2)
        return f"{m.group(1)}{_new_spec(spec, package, version)}{m.group(1)}" if _req_name(spec) == target else m.group(0)

    return _REQ_STRING.sub(swap, text)


def load_pyproject(repo: Path) -> dict:
    path = repo / "pyproject.toml"
    return tomllib.loads(path.read_text()) if path.exists() else {}

"""Run inside a throwaway venv: print the public API of one installed distribution as JSON.

Usage: python apidiff_probe.py <distribution-name>
Output: {"module.attr": "signature or kind", ...}
"""

import importlib
import importlib.metadata as md
import inspect
import json
import pkgutil
import re
import sys
import warnings

MAX_SYMBOLS = 20000


def norm(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def top_level_modules(dist: str) -> list[str]:
    wanted = norm(dist)
    return sorted(
        name for name, dists in md.packages_distributions().items()
        if not name.startswith("_") and any(norm(d) == wanted for d in dists)
    )


def describe(obj) -> str:
    try:
        if inspect.isclass(obj):
            return "class" + str(inspect.signature(obj))
        if callable(obj):
            return "def" + str(inspect.signature(obj))
    except (TypeError, ValueError):
        return "class" if inspect.isclass(obj) else "callable"
    return type(obj).__name__


def main() -> None:
    warnings.simplefilter("ignore")
    api: dict[str, str] = {}
    for top in top_level_modules(sys.argv[1]):
        try:
            root = importlib.import_module(top)
        except Exception:
            continue
        modules = [root]
        if hasattr(root, "__path__"):
            for info in pkgutil.walk_packages(root.__path__, top + ".", onerror=lambda _: None):
                if any(part.startswith("_") for part in info.name.split(".")[1:]):
                    continue
                try:
                    modules.append(importlib.import_module(info.name))
                except Exception:
                    pass
        for module in modules:
            for name, obj in sorted(vars(module).items()):
                if name.startswith("_") or inspect.ismodule(obj):
                    continue
                key = f"{module.__name__}.{name}"
                api[key] = describe(obj)
                if inspect.isclass(obj) and getattr(obj, "__module__", "") == module.__name__:
                    for member, value in sorted(vars(obj).items()):
                        if not member.startswith("_") or member in ("__init__",):
                            api[f"{key}.{member}"] = describe(value) if callable(value) else type(value).__name__
                if len(api) >= MAX_SYMBOLS:
                    break
    json.dump(api, sys.stdout)


if __name__ == "__main__":
    main()

"""Research a package upgrade: versions from PyPI, docs and release notes, and a real API diff."""

import html
import json
import re
from pathlib import Path

import httpx
import neatlogs
from packaging.version import InvalidVersion, Version

from .workspace import sh, tail

PYPI = "https://pypi.org/pypi/{}/json"
PROBE = Path(__file__).with_name("apidiff_probe.py")
SOURCE_CAP = 30000
USEFUL_LINK = re.compile(r"change|release|history|news|migrat|upgrad|doc", re.I)


def http_get(url: str, timeout: float = 20) -> httpx.Response:
    return httpx.get(url, timeout=timeout, follow_redirects=True,
                     headers={"User-Agent": "upshift/0.1 (dependency upgrade agent)"})


def pypi_info(package: str) -> dict:
    response = http_get(PYPI.format(package))
    response.raise_for_status()
    return response.json()


def resolve_target(info: dict, wanted: str | None) -> str:
    """`None` → latest stable; `2` or `2.7` → newest stable release with that prefix; else exact."""
    releases = []
    for raw, files in info["releases"].items():
        try:
            version = Version(raw)
        except InvalidVersion:
            continue
        if not version.is_prerelease and files and not all(f.get("yanked") for f in files):
            releases.append(version)
    releases.sort()
    if not wanted:
        return str(releases[-1])
    prefix = [int(p) for p in wanted.split(".")]
    if len(prefix) >= 3 and Version(wanted) in releases:
        return wanted
    matches = [v for v in releases if list(v.release[: len(prefix)]) == prefix]
    if not matches:
        raise ValueError(f"no stable release matches {wanted!r}")
    return str(matches[-1])


def html_to_text(raw: str) -> str:
    raw = re.sub(r"(?is)<(script|style|nav|header|footer)[^>]*>.*?</\1>", " ", raw)
    raw = re.sub(r"(?i)<br\s*/?>|</(p|div|li|h\d|tr|pre)>", "\n", raw)
    raw = re.sub(r"<[^>]+>", " ", raw)
    text = html.unescape(raw)
    text = re.sub(r"[ \t]+", " ", text)
    return re.sub(r"\n\s*\n+", "\n\n", text).strip()


@neatlogs.span(kind="TOOL", tool_name="fetch_url")
def fetch_text(url: str, cap: int = SOURCE_CAP) -> str:
    try:
        response = http_get(url)
    except httpx.HTTPError as exc:
        return f"[fetch failed: {exc}]"
    if response.status_code >= 400:
        return f"[HTTP {response.status_code} for {url}]"
    body = response.text
    if "html" in response.headers.get("content-type", ""):
        body = html_to_text(body)
    return body[:cap] + ("\n...[truncated]" if len(body) > cap else "")


def github_repo(urls: dict) -> str | None:
    for url in urls.values():
        m = re.match(r"https?://github\.com/([^/]+/[^/#?]+)", url or "")
        if m:
            return m.group(1).removesuffix(".git")
    return None


@neatlogs.span(kind="RETRIEVER", tool_name="release_notes")
def github_release_notes(repo: str, old: str, new: str, cap: int = SOURCE_CAP) -> str:
    """Release notes for versions in (old, new], newest first."""
    try:
        response = http_get(f"https://api.github.com/repos/{repo}/releases?per_page=100")
        response.raise_for_status()
    except httpx.HTTPError as exc:
        return f"[release notes unavailable: {exc}]"
    lo, hi = Version(old), Version(new)
    parts = []
    for release in response.json():
        tag = re.sub(r"^[^\d]*", "", release.get("tag_name", ""))
        try:
            version = Version(tag)
        except InvalidVersion:
            continue
        if lo < version <= hi and not version.is_prerelease:
            parts.append(f"## {release['tag_name']}\n{release.get('body') or ''}")
    text = "\n\n".join(parts)
    return text[:cap] + ("\n...[truncated]" if len(text) > cap else "") if text else "[no GitHub releases in range]"


@neatlogs.span(kind="TOOL", tool_name="api_diff")
def api_diff(package: str, old: str, new: str, python: str, scratch: Path) -> dict:
    """Install both versions side by side and diff their public symbols and signatures."""
    surfaces = {}
    for label, version in (("old", old), ("new", new)):
        venv = scratch / f"apidiff-{label}"
        if not venv.exists():
            sh(["uv", "venv", "-q", "--python", python, str(venv)])
        py = str(venv / "bin" / "python")
        out = sh(["uv", "pip", "install", "-q", "--python", py, f"{package}=={version}"])
        if out.returncode != 0:
            return {"error": f"could not install {package}=={version}: {tail(out.stderr, 1500)}"}
        out = sh([py, "-I", str(PROBE), package], timeout=300)
        if out.returncode != 0:
            return {"error": f"probe failed for {version}: {tail(out.stderr, 1500)}"}
        surfaces[label] = json.loads(out.stdout or "{}")
    before, after = surfaces["old"], surfaces["new"]
    return {
        "removed": sorted(set(before) - set(after)),
        "added": sorted(set(after) - set(before)),
        "changed": {k: [before[k], after[k]] for k in sorted(set(before) & set(after)) if before[k] != after[k]},
        "old_count": len(before),
        "new_count": len(after),
    }


def format_api_diff(diff: dict, cap: int = 20000) -> str:
    if "error" in diff:
        return f"[API diff unavailable: {diff['error']}]"
    lines = [f"Public symbols: {diff['old_count']} before, {diff['new_count']} after.",
             f"REMOVED ({len(diff['removed'])}):"]
    lines += [f"- {name}" for name in diff["removed"]]
    lines.append(f"SIGNATURE CHANGED ({len(diff['changed'])}):")
    lines += [f"~ {name}: {a}  ->  {b}" for name, (a, b) in diff["changed"].items()]
    lines.append(f"ADDED: {len(diff['added'])} symbols (not listed)")
    text = "\n".join(lines)
    return text[:cap] + ("\n...[truncated]" if len(text) > cap else "")


def candidate_links(info: dict) -> dict[str, str]:
    urls = info["info"].get("project_urls") or {}
    if info["info"].get("home_page"):
        urls.setdefault("Homepage", info["info"]["home_page"])
    return {k: v for k, v in urls.items() if v}


@neatlogs.span(kind="RETRIEVER", tool_name="gather_sources")
def gather(package: str, old: str, new: str, python: str, scratch: Path) -> dict:
    """Everything the playbook writer starts from. It can fetch more links itself."""
    info = pypi_info(package)
    links = candidate_links(info)
    repo = github_repo(links)
    docs = {name: fetch_text(url, cap=12000) for name, url in links.items() if USEFUL_LINK.search(name + url)}
    diff = api_diff(package, old, new, python, scratch)
    return {
        "package": package,
        "old": old,
        "new": new,
        "links": links,
        "docs": docs,
        "release_notes": github_release_notes(repo, old, new) if repo else "[no GitHub repo linked on PyPI]",
        "api_diff": format_api_diff(diff),
    }

